using System;

// Positional record: parameters become init-only properties
public record Person(string FirstName, string LastName, int Age);

class Program
{
    static void Main()
    {
        // Create a record instance
        var alice = new Person("Alice", "Johnson", 28);

        // Properties are accessible by name
        Console.WriteLine(alice.FirstName); // Alice
        Console.WriteLine(alice.LastName);  // Johnson
        Console.WriteLine(alice.Age);       // 28

        // 'with' creates a copy with modified properties
        var olderAlice = alice with { Age = 30 };
        Console.WriteLine(olderAlice);
        Console.WriteLine($"Same object? {ReferenceEquals(alice, olderAlice)}"); // False
    }
}

using System;

public record Product
{
    // Init-only: can be set during creation, but not modified after
    public int Id { get; init; }
    public string Name { get; init; } = string.Empty;

    // Mutable property (allowed if explicitly declared)
    public decimal Price { get; set; }

    // Read-only property with expression body
    public string Description => $"{Name} (ID: {Id})";

    // Custom constructor for validation
    public Product(int id, string name)
    {
        if (id <= 0) throw new ArgumentOutOfRangeException(nameof(id));
        Id = id;
        Name = name ?? throw new ArgumentNullException(nameof(name));
    }
}

class Program
{
    static void Main()
    {
        var product = new Product(1, "Laptop") { Price = 999.99m };
        Console.WriteLine(product.Description);

        // product.Price = 899.99m; // OK — mutable property
        // product.Name = "Desktop"; // Error — init-only property
    }
}

using System;

// Record — value-based equality
public record User(string Name, int Id);

// Class — reference-based equality
public class UserClass
{
    public string Name { get; set; } = string.Empty;
    public int Id { get; get; }
}

class Program
{
    static void Main()
    {
        // Records: equal if values match
        var user1 = new User("Alice", 1);
        var user2 = new User("Alice", 1);
        Console.WriteLine(user1 == user2);          // True — same values!
        Console.WriteLine(user1.Equals(user2));       // True
        Console.WriteLine(ReferenceEquals(user1, user2)); // False — different objects

        // Classes: equal only if same reference
        var c1 = new UserClass { Name = "Alice", Id = 1 };
        var c2 = new UserClass { Name = "Alice", Id = 1 };
        Console.WriteLine(c1 == c2);                   // False — different references
        Console.WriteLine(ReferenceEquals(c1, c2));    // False

        // 'with' expression for non-destructive mutation
        var updatedUser = user1 with { Name = "Alicia" };
        Console.WriteLine(user1);    // User { Name = Alice, Id = 1 }
        Console.WriteLine(updatedUser); // User { Name = Alicia, Id = 1 }
    }
}

using System;

class Program
{
    static void Describe(object obj)
    {
        // Type patterns match the runtime type and cast simultaneously
        switch (obj)
        {
            case string s:
                Console.WriteLine($"String of length {s.Length}: {s}");
                break;
            case int i when i > 100:
                Console.WriteLine($"Large integer: {i}");
                break;
            case int i:
                Console.WriteLine($"Small integer: {i}");
                break;
            case null:
                Console.WriteLine("Value is null");
                break;
            default:
                Console.WriteLine($"Unknown type: {obj.GetType().Name}");
                break;
        }
    }

    static void Main()
    {
        Describe("hello");
        Describe(42);
        Describe(150);
        Describe(null);
        Describe(3.14);
    }
}

using System;

class Program
{
    // Relational patterns: >=, >, <=, <
    static string GetGrade(int score) => score switch
    {
        >= 90 => "A",
        >= 80 => "B",
        >= 70 => "C",
        >= 60 => "D",
        < 60 => "F",
        _ => "Invalid"
    };

    static void Main()
    {
        int[] scores = { 95, 82, 73, 61, 45 };

        foreach (int score in scores)
        {
            Console.WriteLine($"Score {score}: Grade {GetGrade(score)}");
        }

        // Logical patterns: and, or, not
        Console.WriteLine(DescribeTemperature(25));
    }

    static string DescribeTemperature(int celsius) => celsius switch
    {
        < 0 => "Freezing",
        >= 0 and < 15 => "Cold",
        >= 15 and < 25 => "Pleasant",
        >= 25 and < 35 => "Warm",
        _ => "Hot"
    };
}

using System;

public record Order(int Id, decimal Total, string Status);

class Program
{
    static string GetOrderAction(Order order) => order switch
    {
        { Status: "Pending", Total: > 1000 } => "Escalate to manager",
        { Status: "Pending" } => "Process normally",
        { Status: "Shipped" } => "Track delivery",
        { Status: "Cancelled" } => "Refund customer",
        _ => "Contact support"
    };

    static void Main()
    {
        Order[] orders =
        {
            new Order(1, 500m, "Pending"),
            new Order(2, 1500m, "Pending"),
            new Order(3, 75m, "Shipped"),
            new Order(4, 200m, "Cancelled")
        };

        foreach (Order order in orders)
        {
            Console.WriteLine($"Order {order.Id}: {GetOrderAction(order)}");
        }
    }
}

using System;

class Program
{
    static string DescribeArray(int[] numbers) => numbers switch
    {
        [] => "Empty array",
        [var single] => $"Single element: {single}",
        [1, 2, 3] => "Starts with 1, 2, 3",
        [var first, .., var last] => $"Starts with {first}, ends with {last}",
        [..] => "Has multiple elements"
    };

    static void Main()
    {
        Console.WriteLine(DescribeArray(Array.Empty<int>()));     // Empty array
        Console.WriteLine(DescribeArray(new[] { 42 }));            // Single element: 42
        Console.WriteLine(DescribeArray(new[] { 1, 2, 3, 4 }));    // Starts with 1, ends with 4
        Console.WriteLine(DescribeArray(new[] { 1, 2, 3 }));       // Starts with 1, 2, 3
    }
}
